# Generated by AI (anthropic, claude-sonnet-5-5, 2026-11-18) — review before use
"""
Name        : carre
Description : Square of the signal (sample-by-sample), with mean-square and peak values
Author      : <name>
Version     : 1.0 — YYYY-MM-DD
Inputs      : 1 signal (any unit)
"""

import numpy as np

from onthesignal import Curve, Param, Result, Signal

# Declared parameters: console form, help, AI tool, (phase 2) web form
PARAMS = [
    Param("remove_mean", bool, False, help="Remove the mean value before squaring"),
    Param("duration", float, 10.0, unit="s",
          help="Duration of the squared signal kept in the result curve (<= 0: whole signal)"),
]


def run(signals: list[Signal], **params) -> Result:
    """Pure computation: no display, no file output."""
    s = signals[0]
    x = np.asarray(s.data, dtype=float)
    if params["remove_mean"]:
        x = x - np.mean(x)
    squared = x ** 2

    result = Result(kind="carre", title=f"carre — {s.name or s.id}",
                    signals=[s.identity()], params=params)
    mean_square = float(np.mean(squared))
    result.add("mean_square", mean_square, "counts²", "Mean of the squared signal")
    result.add("max_square", float(np.max(squared)), "counts²", "Maximum of the squared signal")
    result.add("mean_square_phys", mean_square * s.sensitivity ** 2, f"({s.unit})²",
               "Mean of the squared signal in physical units")

    duration = params["duration"]
    n = squared.size if duration <= 0 else min(squared.size, int(duration * s.sampling_rate))
    result.curves["squared"] = Curve(
        s.times()[:n], squared[:n], label="squared signal", x_label="Time", x_unit="s",
        y_label="Amplitude²", y_unit="counts²",
    )
    return result


def plot(result: Result, fig):
    """Optional: fill a matplotlib figure from the result."""
    c = result.curves["squared"]
    ax = fig.add_subplot()
    ax.plot(c.x, c.y, lw=0.8)
    ax.set_xlabel("Time (s)")
    ax.set_ylabel("Amplitude² (counts²)")
    ax.set_title(result.title)


if __name__ == "__main__":
    # Standalone run: python scripts/carre.py --files data/*.mseed --out results.csv
    from onthesignal.scripts import main

    main(run, PARAMS, plot)
